//
// NOVEL (hand-authored) — not generated by CLI Printing Press.
//
// N131.5.5 F-2: `activities download-original <id>` returned
// HTTP 406 NotAcceptableException from Garmin on every account and every
// activity, with or without --deliver, while `activities get` and
// `activities splits` answered 200 for the same id on the same token. The
// request's Accept header was application/octet-stream, which is not a type
// Garmin will serve for /download-service/files/activity/{id}: it serves the
// ZIP the spec's own 200 response names first.
//
// The server below is the minimum that can tell the two apart: it negotiates
// the way a 406 says a server negotiates — it serves application/zip and
// refuses an Accept that asks for neither application/zip nor */*.

package cli

import (
	"archive/zip"
	"bytes"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"
)

func zipFixture(t *testing.T) []byte {
	t.Helper()
	var buf bytes.Buffer
	zw := zip.NewWriter(&buf)
	w, err := zw.Create("activity.fit")
	if err != nil {
		t.Fatalf("building the zip fixture: %v", err)
	}
	if _, err := w.Write([]byte("FIT")); err != nil {
		t.Fatalf("writing the zip fixture: %v", err)
	}
	if err := zw.Close(); err != nil {
		t.Fatalf("closing the zip fixture: %v", err)
	}
	return buf.Bytes()
}

func TestActivitiesDownloadOriginalAsksForATypeGarminServes(t *testing.T) {
	payload := zipFixture(t)
	var accept string
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if !strings.HasPrefix(r.URL.Path, "/download-service/files/activity/") {
			w.WriteHeader(http.StatusNotFound)
			return
		}
		accept = r.Header.Get("Accept")
		serves := false
		for _, part := range strings.Split(accept, ",") {
			switch strings.TrimSpace(strings.SplitN(part, ";", 2)[0]) {
			case "application/zip", "*/*":
				serves = true
			}
		}
		if !serves {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusNotAcceptable)
			_, _ = w.Write([]byte(`{"error":"NotAcceptableException"}`))
			return
		}
		w.Header().Set("Content-Type", "application/zip")
		_, _ = w.Write(payload)
	}))
	defer server.Close()

	home := t.TempDir()
	t.Setenv("GARMIN_HOME", home)
	t.Setenv("GARMIN_BASE_URL", server.URL)
	out := filepath.Join(t.TempDir(), "original.zip")

	root := RootCmd()
	var stdout, stderr bytes.Buffer
	root.SetOut(&stdout)
	root.SetErr(&stderr)
	root.SetArgs([]string{"activities", "download-original", "1234567890", "--deliver", "file:" + out, "--quiet"})
	if err := root.Execute(); err != nil {
		t.Fatalf("download-original failed with Accept %q: %v\nstderr: %s", accept, err, stderr.String())
	}
	if accept == "" {
		t.Fatal("the server never saw the download request")
	}
	if strings.Contains(accept, "application/octet-stream") {
		t.Errorf("Accept = %q: Garmin answers that with 406 NotAcceptableException", accept)
	}
}
